// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ProxiedVault
/// @notice The implementation actually running behind the proxy.
contract ProxiedVault {
    /// @dev The exchange rate is 1:1 only while the vault holds no accrued fee; once fees accrue
    ///      the share price is strictly greater than 1e18 and a 1:1 assumption over-credits redeemers.
    function exchangeRate() external view returns (uint256) {
        return _rate;
    }

    uint256 internal _rate;
}
